def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    desperate_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100 and opp.get('budget', 0) >= 100:
                    rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 20.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    if desperate_opponents >= 2:
        urgency += 1

    if urgency >= 7:
        bid = max(95.0, max_prev + 3.0)
    elif urgency >= 5:
        bid = max(72.0, min(110.0, avg_prev * 0.7 + 8.0))
    elif urgency >= 3:
        if max_prev >= 120:
            bid = 46.0 if loose_supply else 58.0
        else:
            bid = max(42.0, min(75.0, max_prev * 0.55 + 6.0))
    else:
        if rich_aggressive >= 2 or max_prev >= 120:
            bid = 18.0 if loose_supply else 26.0
        elif max_prev >= 80:
            bid = 24.0 if loose_supply else 34.0
        else:
            bid = 32.0

    if day >= 8:
        bid += 8.0
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        bid += 12.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 120.0
    elif day <= 9:
        reserve_floor = 50.0

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor + min(20.0, DAILY_SALARY * 0.3)

    bid = min(bid, budget, max_affordable)
    if urgency >= 5:
        bid = min(max(bid, 65.0), budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Check previous traces for hints of yesterday's bids
    max_prev_bid = 0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])

    # Base bid strategy
    if hp <= 2:
        # Desperate: bid high to get water
        bid = min(budget, DAILY_SALARY * 1.0)
    elif hp <= 4:
        bid = min(budget, DAILY_SALARY * 0.85)
    else:
        # Healthy: adjust based on supply and opponent history
        if max_prev_bid > 120:
            # Aggressive opponents yesterday, likely high today
            bid = min(budget, max(DAILY_SALARY * 0.7, max_prev_bid - 5))
        else:
            # Moderate supply-based bid
            if supply > 20:
                bid = min(budget, DAILY_SALARY * 0.7)
            else:
                bid = min(budget, DAILY_SALARY * 0.85)

    # Ensure bid is within budget and not less than 0
    bid = max(0, min(budget, bid))
    # To avoid float index errors, no list indexing used
    return float(bid)
